// Merge webhook payload + Instantly lead record + latest reply into one clean object.
const whRaw = $('Webhook').item.json;
const wh = whRaw.body ?? whRaw; // Webhook v2 nests payload under .body

const email = String(wh.lead_email ?? wh.email ?? '').trim().toLowerCase();

// --- Lead record (custom_variables carry industry / location / linkedin_url) ---
let leadRec = {};
try {
  const lr = $('Get Lead Record').item.json;
  leadRec = (lr.items && lr.items[0]) || (lr.data && lr.data[0]) || (Array.isArray(lr) ? lr[0] : null) || {};
  if (leadRec.error) leadRec = {};
} catch (e) { /* node failed -> degrade gracefully */ }
const cv = leadRec.custom_variables ?? leadRec.customVariables ?? {};

// --- Latest reply from this lead (for signature parsing) ---
let replyText = '', replyHtml = '';
try {
  const all = $('Get Latest Reply').all().map(i => i.json);
  const items = all.flatMap(x => x.items ?? x.data ?? (x.lead ? [x] : []));
  const mine = items.filter(e => String(e.lead ?? '').toLowerCase() === email);
  mine.sort((a, b) => new Date(b.timestamp_email ?? b.timestamp_created ?? 0) - new Date(a.timestamp_email ?? a.timestamp_created ?? 0));
  if (mine.length) {
    replyText = mine[0].body?.text ?? '';
    replyHtml = mine[0].body?.html ?? '';
  }
} catch (e) { /* no reply body -> signature source yields nothing */ }

// --- Location parse: Sales Nav free text -> city + 2-letter state ---
const STATES = {'alabama':'AL','alaska':'AK','arizona':'AZ','arkansas':'AR','california':'CA','colorado':'CO','connecticut':'CT','delaware':'DE','florida':'FL','georgia':'GA','hawaii':'HI','idaho':'ID','illinois':'IL','indiana':'IN','iowa':'IA','kansas':'KS','kentucky':'KY','louisiana':'LA','maine':'ME','maryland':'MD','massachusetts':'MA','michigan':'MI','minnesota':'MN','mississippi':'MS','missouri':'MO','montana':'MT','nebraska':'NE','nevada':'NV','new hampshire':'NH','new jersey':'NJ','new mexico':'NM','new york':'NY','north carolina':'NC','north dakota':'ND','ohio':'OH','oklahoma':'OK','oregon':'OR','pennsylvania':'PA','rhode island':'RI','south carolina':'SC','south dakota':'SD','tennessee':'TN','texas':'TX','utah':'UT','vermont':'VT','virginia':'VA','washington':'WA','west virginia':'WV','wisconsin':'WI','wyoming':'WY','district of columbia':'DC','washington dc':'DC','washington d.c.':'DC'};
const ABBREVS = new Set(Object.values(STATES));
const METROS = {'san francisco bay':['San Francisco','CA'],'greater boston':['Boston','MA'],'greater new york city':['New York','NY'],'new york city metropolitan':['New York','NY'],'greater chicago':['Chicago','IL'],'greater seattle':['Seattle','WA'],'greater los angeles':['Los Angeles','CA'],'los angeles metropolitan':['Los Angeles','CA'],'dallas-fort worth metroplex':['Dallas','TX'],'greater houston':['Houston','TX'],'greater philadelphia':['Philadelphia','PA'],'atlanta metropolitan':['Atlanta','GA'],'greater atlanta':['Atlanta','GA'],'miami-fort lauderdale':['Miami','FL'],'greater miami':['Miami','FL'],'greater denver':['Denver','CO'],'denver metropolitan':['Denver','CO'],'greater phoenix':['Phoenix','AZ'],'phoenix metropolitan':['Phoenix','AZ'],'greater minneapolis-st. paul':['Minneapolis','MN'],'greater san diego':['San Diego','CA'],'san diego metropolitan':['San Diego','CA'],'greater austin':['Austin','TX'],'austin metropolitan':['Austin','TX'],'washington dc-baltimore':['Washington','DC'],'greater washington':['Washington','DC'],'greater nashville':['Nashville','TN'],'nashville metropolitan':['Nashville','TN'],'greater tampa bay':['Tampa','FL'],'tampa bay':['Tampa','FL'],'greater orlando':['Orlando','FL'],'greater st. louis':['St. Louis','MO'],'greater detroit':['Detroit','MI'],'detroit metropolitan':['Detroit','MI'],'greater pittsburgh':['Pittsburgh','PA'],'greater charlotte':['Charlotte','NC'],'charlotte metro':['Charlotte','NC'],'greater raleigh':['Raleigh','NC'],'raleigh-durham':['Raleigh','NC'],'greater portland':['Portland','OR'],'portland metropolitan':['Portland','OR'],'salt lake city metropolitan':['Salt Lake City','UT'],'greater salt lake city':['Salt Lake City','UT'],'las vegas metropolitan':['Las Vegas','NV'],'greater las vegas':['Las Vegas','NV'],'greater indianapolis':['Indianapolis','IN'],'greater columbus':['Columbus','OH'],'columbus, ohio metropolitan':['Columbus','OH'],'greater cleveland':['Cleveland','OH'],'cincinnati metropolitan':['Cincinnati','OH'],'greater cincinnati':['Cincinnati','OH'],'kansas city metropolitan':['Kansas City','MO'],'greater kansas city':['Kansas City','MO'],'greater sacramento':['Sacramento','CA'],'sacramento metropolitan':['Sacramento','CA'],'greater milwaukee':['Milwaukee','WI'],'greater jacksonville':['Jacksonville','FL'],'greater san antonio':['San Antonio','TX'],'san antonio metropolitan':['San Antonio','TX'],'oklahoma city metropolitan':['Oklahoma City','OK'],'greater richmond':['Richmond','VA'],'richmond metropolitan':['Richmond','VA'],'greater hartford':['Hartford','CT'],'greater new orleans':['New Orleans','LA'],'greater memphis':['Memphis','TN'],'louisville metropolitan':['Louisville','KY'],'greater louisville':['Louisville','KY'],'greater buffalo':['Buffalo','NY'],'buffalo-niagara falls':['Buffalo','NY'],'omaha metropolitan':['Omaha','NE'],'greater omaha':['Omaha','NE'],'greater tucson':['Tucson','AZ'],'greater albuquerque':['Albuquerque','NM'],'greater boise':['Boise','ID'],'boise metropolitan':['Boise','ID']};

function parseLocation(loc) {
  if (!loc || typeof loc !== 'string') return { city: null, state: null };
  const raw = loc.trim().replace(/,?\s*(united states|usa|u\.s\.a?\.?)$/i, '').trim();
  if (!raw) return { city: null, state: null };
  const lower = raw.toLowerCase();

  // Metro-area phrasing ("San Francisco Bay Area", "Greater Boston Area")
  const metroKey = lower.replace(/\s*area$/,'').replace(/\s*region$/,'').trim();
  for (const [k, v] of Object.entries(METROS)) {
    if (metroKey.includes(k)) return { city: v[0], state: v[1] };
  }

  const parts = raw.split(',').map(p => p.trim()).filter(Boolean);
  if (parts.length >= 2) {
    const city = parts[0];
    const stRaw = parts[1];
    const stLower = stRaw.toLowerCase();
    if (STATES[stLower]) return { city, state: STATES[stLower] };
    const ab = stRaw.replace(/\./g, '').toUpperCase();
    if (ABBREVS.has(ab)) return { city, state: ab };
    return { city, state: null };
  }
  // Single token: maybe it's just a state
  if (STATES[lower]) return { city: null, state: STATES[lower] };
  const ab1 = raw.replace(/\./g, '').toUpperCase();
  if (ABBREVS.has(ab1)) return { city: null, state: ab1 };
  return { city: raw, state: null };
}

const locField = cv.location ?? leadRec.location ?? '';
const { city, state } = parseLocation(String(locField));

return [{ json: {
  event_type: wh.event_type ?? '',
  campaign_name: wh.campaign_name ?? '',
  firstName: wh.firstName ?? leadRec.first_name ?? cv.first_name ?? '',
  lastName: wh.lastName ?? leadRec.last_name ?? cv.last_name ?? '',
  email,
  companyName: wh.companyName ?? leadRec.company_name ?? cv.company_name ?? '',
  industry: cv.company_industry ?? '',
  locationRaw: String(locField),
  city, state,
  linkedinUrl: cv.linkedin_url ?? '',
  companyPhone: String(cv.company_phone ?? wh.phone ?? ''),
  replyText, replyHtml,
} }];

// Extract phone numbers from the lead's reply signature. Free, always runs.
const k = $json;

function stripHtml(html) {
  return String(html || '')
    .replace(/<style[\s\S]*?<\/style>/gi, ' ')
    .replace(/<script[\s\S]*?<\/script>/gi, ' ')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|tr|li)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&amp;/g, '&');
}

let text = k.replyText && k.replyText.trim() ? k.replyText : stripHtml(k.replyHtml);

// Cut quoted/forwarded history so we don't scrape our own signature back
const cutMarkers = [/\nOn .{5,120}wrote:/, /-{3,}\s*Original Message\s*-{3,}/i, /\nFrom:\s.+\nSent:\s/i, /\n>{1}\s/];
for (const m of cutMarkers) {
  const match = text.match(m);
  if (match && match.index > 40) text = text.slice(0, match.index);
}

const companyDigits = String(k.companyPhone || '').replace(/\D/g, '').slice(-10);

const sigNumbers = [];
const seen = new Set();
const re = /(?:\+?1[\s.\-]?)?\(?([2-9]\d{2})\)?[\s.\-]?(\d{3})[\s.\-]?(\d{4})\b/g;
let m;
while ((m = re.exec(text)) !== null) {
  const digits = (m[1] + m[2] + m[3]);
  if (seen.has(digits)) continue;
  seen.add(digits);
  if (companyDigits && digits === companyDigits) continue; // company switchboard

  const before = text.slice(Math.max(0, m.index - 25), m.index).toLowerCase();
  let type = 'unknown', label = 'unlabeled';
  if (/\bf(ax)?\s*[.:]/.test(before) || /\bfax\b/.test(before)) continue; // fax -> discard
  if (/\b(m|c)\s*[.:]|\bcell\b|\bmob(ile)?\b|\btext\b/.test(before)) { type = 'mobile'; label = 'labeled mobile/cell'; }
  else if (/\b(o|t|d|w)\s*[.:]|\btel\b|\bdirect\b|\boffice\b|\bmain\b|\bwork\b|\bphone\s*[.:]/.test(before)) { type = 'office'; label = 'labeled office/direct'; }

  sigNumbers.push({ digits, type, label });
}

return [{ json: { ...k, sigNumbers } }];

// Collect candidates from all four sources, normalize, dedupe, score, build the alert email.
const k = $('Parse Signature').item.json;
const cfg = $('Config').item.json;

function digitsOf(s) { return String(s || '').replace(/\D/g, '').slice(-10); }
function pretty(d) { return d.length === 10 ? `+1 (${d.slice(0,3)}) ${d.slice(3,6)}-${d.slice(6)}` : d; }
function esc(s) { return String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }

const companyDigits = digitsOf(k.companyPhone);
const candidates = []; // { digits, score, type, source, note }

// --- 1. Email signature ---
for (const n of (k.sigNumbers || [])) {
  if (n.type === 'mobile')      candidates.push({ digits: n.digits, score: 95, type: 'mobile',  source: 'email signature', note: n.label });
  else if (n.type === 'office') candidates.push({ digits: n.digits, score: 40, type: 'office',  source: 'email signature', note: n.label });
  else                          candidates.push({ digits: n.digits, score: 70, type: 'unknown', source: 'email signature', note: n.label });
}

// --- 2 & 3. FastPeopleSearch / TruePeopleSearch (Apify dataset items) ---
function harvestScraper(nodeName, sourceLabel) {
  let items = [];
  try { items = $(nodeName).all().map(i => i.json); } catch (e) { return; }
  for (const rec of items) {
    if (!rec || rec.error || !Array.isArray(rec.phones)) continue;
    const recName = String(rec.name ?? `${rec.firstName ?? ''} ${rec.lastName ?? ''}`).toLowerCase();
    const fn = String(k.firstName).toLowerCase(), ln = String(k.lastName).toLowerCase();
    if (fn && ln && !(recName.includes(fn) && recName.includes(ln))) continue; // wrong person
    const addr = String(rec.currentAddress ?? '').toLowerCase();
    const cityMatch = !!(k.city && addr.includes(String(k.city).toLowerCase()));
    const base = cityMatch ? 75 : 50;
    const locNote = cityMatch ? `${k.city}, ${k.state} match` : `${k.state || 'state'}-level match only`;
    rec.phones.forEach((p, idx) => {
      const d = digitsOf(p);
      if (d.length !== 10 || d === companyDigits) return;
      // First listed number is typically the primary/most recent line
      candidates.push({ digits: d, score: idx === 0 ? base : base - 10, type: 'unknown', source: sourceLabel, note: `${locNote}${idx === 0 ? ', primary listing' : ''}` });
    });
  }
}
harvestScraper('FastPeopleSearch', 'FastPeopleSearch');
harvestScraper('TruePeopleSearch', 'TruePeopleSearch');

// --- 4. LeadMagic mobile-finder ---
try {
  const lm = $('LeadMagic Mobile').item.json;
  const d = digitsOf(lm.mobile_number);
  if (d.length === 10) candidates.push({ digits: d, score: 90, type: 'mobile', source: 'LeadMagic', note: 'B2B mobile-finder' });
} catch (e) { /* skipped or failed */ }

// --- Dedupe (keep best score, remember all sources) + cross-source bonus ---
const byDigits = new Map();
for (const c of candidates) {
  const cur = byDigits.get(c.digits);
  if (!cur) byDigits.set(c.digits, { ...c, sources: new Set([c.source]) });
  else {
    cur.sources.add(c.source);
    if (c.score > cur.score) { cur.score = c.score; cur.note = c.note; cur.source = c.source; }
    if (c.type === 'mobile') cur.type = 'mobile';
    else if (cur.type === 'unknown' && c.type === 'office') cur.type = 'office';
  }
}
const merged = [...byDigits.values()].map(c => {
  if (c.sources.size >= 2) { c.score = Math.min(99, c.score + 15); c.note += ` — corroborated by ${c.sources.size} sources`; }
  c.sourceList = [...c.sources].join(' + ');
  return c;
});

const mobiles = merged.filter(c => c.type !== 'office').sort((a, b) => b.score - a.score);
const others  = merged.filter(c => c.type === 'office').sort((a, b) => b.score - a.score);

// --- Email ---
const subject = `New Lead: ${k.firstName} ${k.lastName} phone number`.replace(/\s+/g, ' ').trim();

function lines(list) {
  return list.map(c => `${esc(pretty(c.digits))} &mdash; ${c.score}% <span style="color:#666">(${esc(c.sourceList)}: ${esc(c.note)})</span>`).join('<br>');
}

let numbersHtml;
if (!merged.length) {
  numbersHtml = '<em>No phone numbers found across signature, FastPeopleSearch, TruePeopleSearch, or LeadMagic.</em>';
} else {
  numbersHtml = mobiles.length ? `<strong>Cell numbers found:</strong><br>${lines(mobiles)}` : '<em>No cell numbers found.</em>';
  if (others.length) numbersHtml += `<br><br><strong>Other numbers found:</strong><br>${lines(others)}`;
}

const html = [
  `<strong>${esc(k.companyName || 'Unknown company')}</strong>`,
  esc(k.industry || 'Industry unknown'),
  esc(`${k.firstName} ${k.lastName}`.trim()),
  '',
  numbersHtml,
  '',
  `<span style="color:#999;font-size:12px">Campaign: ${esc(k.campaign_name)} &middot; Lead: ${esc(k.email)}${k.locationRaw ? ' &middot; ' + esc(k.locationRaw) : ''}</span>`,
].join('<br>');

return [{ json: { to: cfg.ALERT_TO, subject, html, mobilesFound: mobiles.length, othersFound: others.length } }];
